param([string]$Exe="$PSScriptRoot/../FileTransferApp/x64/Debug/FileTransferAppGui.exe")
$ErrorActionPreference='Stop'
. "$PSScriptRoot/n_to_1.ps1" -Exe $Exe -HelpersOnly
function Discover($observer,$target,$server){
 $role=if($server){'S'}else{'C'};$packet="FTA-DISC|2|R|$($target.Instance)|$($target.Port)|fixture|$role|$($target.ID)"
 $u=[Net.Sockets.UdpClient]::new();try{$u.Client.SetSocketOption([Net.Sockets.SocketOptionLevel]::IP,[Net.Sockets.SocketOptionName]::MulticastInterface,[Net.IPAddress]::Loopback.GetAddressBytes());$bytes=[Text.Encoding]::UTF8.GetBytes($packet);[void]$u.Send($bytes,$bytes.Length,'239.255.90.8',9001)}finally{$u.Dispose()}
 $w=[Diagnostics.Stopwatch]::StartNew();while($w.ElapsedMilliseconds -lt 5000){$rows=$observer.G.Devices();for($i=0;$i -lt $rows.Length;$i++){if($rows[$i].Contains('['+$target.Instance.Substring(0,8)+']')){$observer.G.SelectDevice($i);return}};Start-Sleep -Milliseconds 20};throw 'Discovery fixture missing'
}
function Register($observer,$target,$key,$server){Discover $observer $target $server;$observer.G.Set(147,$key);$observer.G.Click(145);$observer.G.Wait(108,('Registered N:1 peer saved: '+$target.ID))}
function Direct($c,$s){$c.G.Set(101,'127.0.0.1');$c.G.Set(102,[string]$s.Port);$c.G.Click(137)}
function Raw($s,$source=''){$raw=[Net.Sockets.TcpClient]::new();if($source){$raw.Client.Bind([Net.IPEndPoint]::new([Net.IPAddress]::Parse($source),0))};$raw.Connect('127.0.0.1',$s.Port);$raw.GetStream().ReadTimeout=5000;return $raw}
function Line($raw,$line){$b=[Text.Encoding]::UTF8.GetBytes($line+"`n");$raw.GetStream().Write($b,0,$b.Length)}
function Read-Line($raw){$s=$raw.GetStream();$line='';while($line.Length -lt 512){$c=$s.ReadByte();if($c -lt 0){throw 'Connection closed'};if($c -eq 10){return $line};$line+=[char]$c};throw 'Oversized greeting'}
function Greeting($id,$name,$mode='M'){'FTA-C3|'+[Guid]::NewGuid().ToString('N')+'|'+[Guid]::NewGuid().ToString('N')+'|'+$name+'|'+$id+'|C|'+$mode}
function Mac($key,$data){$bytes=New-Object byte[] 32;for($i=0;$i -lt 32;$i++){$bytes[$i]=[Convert]::ToByte($key.Substring(2*$i,2),16)};$h=[Security.Cryptography.HMACSHA256]::new($bytes);try{return ([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($data)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Closed($raw){try{Assert ($raw.GetStream().ReadByte() -eq -1) 'Rejected candidate returned unexpected data'}catch [IO.IOException]{if($_.Exception.InnerException -is [Net.Sockets.SocketException] -and $_.Exception.InnerException.SocketErrorCode -in @([Net.Sockets.SocketError]::ConnectionReset,[Net.Sockets.SocketError]::ConnectionAborted,[Net.Sockets.SocketError]::Shutdown)){return};throw}}
$s=$null;$a=$null;$b=$null;$raw=$null;$pending=@();$rawPeers=@()
try{
 $s=App 'server' $true 'auth-server';$a=App 'a' $false 'same-name';$b=App 'b' $false 'same-name';$keyA='a'*64;$keyB='b'*64
 Register $s $a $keyA $false;Register $a $s $keyA $true;Direct $a $s;$a.G.Wait(107,'Connected:');Count $s 1;Assert (!$s.G.Text(138).Contains('unverified')) 'Auto auth displayed manual prompt';Pass 'registered PeerId/key authenticates automatically without manual approval'
 Register $s $b $keyB $false;Register $b $s ('c'*64) $true;Direct $b $s;$b.G.Wait(141,'key mismatch');Count $s 1;Send $a $s 'existing-peer-survives-key-failure';ChatWait $s $a 'existing-peer-survives-key-failure';Pass 'one client key failure does not affect another session'
 Register $b $s $keyB $true;Start-Sleep -Milliseconds 300;Direct $b $s;$b.G.Wait(107,'Connected:');Count $s 2;Pass 'distinct peers on the same IP use independent shared keys'
 $raw=Raw $s;Line $raw (Greeting $a.ID 'spoof' 'M');$s.G.Wait(141,'manual downgrade refused');$raw.Dispose();$raw=$null;Count $s 2;Pass 'registered identity cannot downgrade to manual approval'
 $greeting=Greeting $a.ID 'raw-auth' 'K';$raw=Raw $s;Line $raw $greeting;$h=(Read-Line $raw).Split('|');$transcript=$greeting+'|'+($h[1..5]-join '|');Assert ($h[6] -eq (Mac $keyA ('server|'+$transcript))) 'Server transcript proof invalid';$proof=Mac $keyA ('client|'+$transcript);Line $raw ('FTA-P3|'+$proof);Assert ((Read-Line $raw).StartsWith('FTA-A3|')) 'Auth completion missing';$s.G.Wait(108,'Duplicate active PeerId refused:');$raw.Dispose();$raw=$null;Count $s 2;Pass 'authenticated duplicate active PeerId is refused without replacing existing session'
 $raw=Raw $s;Line $raw $greeting;[void](Read-Line $raw);Line $raw ('FTA-P3|'+$proof);Closed $raw;$s.G.Wait(141,'key mismatch or replay');$raw.Dispose();$raw=$null;Count $s 2;Pass 'old authentication proof fails with a fresh receiver challenge'
 $raw=Raw $s;$changed=Greeting $a.ID 'changed-name' 'K';Line $raw $changed;$h=(Read-Line $raw).Split('|');$wrong=$changed.Replace('changed-name','original-name')+'|'+($h[1..5]-join '|');Line $raw ('FTA-P3|'+(Mac $keyA ('client|'+$wrong)));Closed $raw;$s.G.Wait(141,'key mismatch or replay');$raw.Dispose();$raw=$null;Pass 'authenticated transcript binds display name, identities, roles and nonces'
 $raw=Raw $s;Line $raw ('FTA-C1|'+('1'*32)+'|'+('2'*32)+'|old-peer');$s.G.Wait(141,'Unsupported N:1 greeting');$raw.Dispose();$raw=$null;Pass 'old GUI greeting is safely rejected without implicit compatibility fallback'
 Select-Peer $s $a;$oldChat=$s.G.Chat;Select-Peer $a $s;$a.G.Click(105);Count $s 1
 $raw=Raw $s '127.0.0.2';$g=Greeting $a.ID 'moved-ip' 'K';Line $raw $g;$h=(Read-Line $raw).Split('|');$t=$g+'|'+($h[1..5]-join '|');Assert ($h[6] -eq (Mac $keyA ('server|'+$t))) 'Moved-IP server proof invalid';Line $raw ('FTA-P3|'+(Mac $keyA ('client|'+$t)));Assert ((Read-Line $raw).StartsWith('FTA-A3|')) 'Moved IP authentication failed';Count $s 2;$raw.Dispose();$raw=$null;Count $s 1;Pass 'registered persistent PeerId authenticates from a different source IP'
 Direct $a $s;$a.G.Wait(107,'Connected:');Count $s 2;Select-Peer $s $a;$s.G.Set(109,'stale-hwnd-marker');$s.G.StaleChatCommand($oldChat);Start-Sleep -Milliseconds 300;Assert ($s.G.Text(109) -eq 'stale-hwnd-marker') 'Stale chat command sent new-session draft';$a.G.UseChat($s.ID);Assert (!$a.G.ChatText().Contains('stale-hwnd-marker')) 'Old HWND command affected reconnected session';Pass 'reconnection replaces chat HWND and rejects queued old-session commands'
 $first=[Guid]::NewGuid().ToString('N');$second=[Guid]::NewGuid().ToString('N');$r1=Raw $s;$r2=Raw $s;$pending=@($r1,$r2);Line $r1 (Greeting $first 'pending-first');Line $r2 (Greeting $second 'pending-second');$s.G.Wait(138,'pending-first');$s.G.Click(139);Assert ((Read-Line $r1).StartsWith('FTA-A3|')) 'First pending candidate not accepted';$s.G.Wait(138,'pending-second');$s.G.Click(139);Assert ((Read-Line $r2).StartsWith('FTA-A3|')) 'Second pending candidate not accepted';Count $s 4;Pass 'simultaneous manual requests retain separate approval tokens'
 $r1.Dispose();$pending=@($r2);Count $s 3;Send $b $s 'pending-disconnect-isolated';ChatWait $s $b 'pending-disconnect-isolated';Pass 'one raw peer disconnect preserves other clients'
 for($i=0;$i -lt 7;$i++){$id=[Guid]::NewGuid().ToString('N');$r=Raw $s;$rawPeers+=@{R=$r;ID=$id};Line $r (Greeting $id ('limit-'+$i));$s.G.Wait(138,('limit-'+$i));$s.G.Click(139);[void](Read-Line $r);Count $s (4+$i)}
 Count $s 10;$raw=Raw $s;try{Line $raw (Greeting ([Guid]::NewGuid().ToString('N')) 'over-limit')}catch{};$s.G.Wait(141,'connection limit');$raw.Dispose();$raw=$null;Count $s 10;Pass 'server enforces ten active clients and refuses the eleventh'
 $s.G.SelectSession($rawPeers[0].ID);$s.G.Click(105);Count $s 9;Send $a $s 'active-peers-survive-selected-disconnect';ChatWait $s $a 'active-peers-survive-selected-disconnect';Pass 'selected-peer disconnect leaves all other sessions operational'
}finally{if($raw){$raw.Dispose()};foreach($p in $pending){$p.Dispose()};foreach($p in $rawPeers){$p.R.Dispose()};foreach($x in @($a,$b,$s)){if($x){try{[IO.File]::WriteAllText((Join-Path $x.Dir 'ui.log'),$x.G.Text(108))}catch{};try{$x.G.Dispose()}catch{}}};"N1 auth artifacts: $run"}
